/* eslint-disable */
/**
 * Drag scroll — scroll an overflowing area by pressing and dragging the mouse (the scrollbar is hidden; classes in drag_scroll.css).
 * GENERATED by tools/sync-java-dom.mjs from web/resources/support/drag_scroll.js — do not edit; change the script and run `npm run dom:sync`.
 *
 * The Java script, same behaviour line by line (ES5 written for a browser global scope — hence "@ts-nocheck": typing it
 * would change it, not port it). What differs from the original lives in tools/sync-java-dom.mjs:
 *   - the script tag with data-targets is replaced by the explicit call startDragScroll(selector) of the page that used it;
 *   - listeners and observers are removed by the function startDragScroll() returns (the cursor classes are taken off too).
 */

/** Binds every element matching `targets` (a CSS selector); the returned function undoes it. */
export function startDragScroll(targets: string): () => void {
    var disposers = [];
    function listen(target, type, fn, opts) {
        target.addEventListener(type, fn, opts);
        disposers.push(function () { target.removeEventListener(type, fn, opts); });
    }
    var observers = [];
    var bound = [];

    var DS_THRESHOLD_PX = 4;                 /* ขยับเกินเท่านี้ถึงนับเป็นลาก (px) */
    var DS_OVERFLOW_SLACK_PX = 1;            /* กันปัดเศษความกว้างจาก zoom/subpixel */
    var DS_SKIP = 'input, textarea, select, button, a, [contenteditable="true"], [draggable="true"]';

    function bind(el) {
        if (!el || el.getAttribute('data-ds-bound') === '1') { return; }
        el.setAttribute('data-ds-bound', '1');
        bound.push(el);
        el.classList.add('ds-scroll');

        var pressed = false, dragged = false, startX = 0, startY = 0, startLeft = 0, startTop = 0;

        /* ไอคอนมือโชว์เฉพาะตอนเลื่อนได้จริง — เนื้อหา/ขนาดจอเปลี่ยนเมื่อไรก็คิดใหม่ */
        function syncCursor() {
            var scrollable = (el.scrollWidth > el.clientWidth + DS_OVERFLOW_SLACK_PX)
                          || (el.scrollHeight > el.clientHeight + DS_OVERFLOW_SLACK_PX);
            el.classList.toggle('ds-grab', scrollable);
        }
        syncCursor();
        listen(window, 'resize', syncCursor);
        if (window.MutationObserver) {
            /* ★ เลื่อนไปวัด layout (scrollWidth/scrollHeight บังคับ reflow) ใน frame ถัดไป
               แทนที่จะทำทันทีตอน mutation เกิด — กันชนกับการวาดแถวที่เพิ่งแทรก (infinite scroll
               ต่อแถวใหม่ถี่ ๆ ตอนเลื่อน) ซึ่งเป็นสาเหตุที่ทำให้เลื่อนกระตุกตรงจังหวะโหลดหน้าถัดไป */
            var syncRaf = null;
            var scheduleSyncCursor = function () {
                if (syncRaf) { return; }
                syncRaf = requestAnimationFrame(function () { syncRaf = null; syncCursor(); });
            };
            var mo = new MutationObserver(scheduleSyncCursor);
            mo.observe(el, { childList: true, subtree: true });
            observers.push(mo);
        }

        el.addEventListener('mousedown', function (e) {
            if (e.button !== 0) { return; }
            if (!el.classList.contains('ds-grab')) { return; }
            if (e.target.closest && e.target.closest(DS_SKIP)) { return; }
            pressed = true; dragged = false;
            startX = e.pageX; startY = e.pageY;
            startLeft = el.scrollLeft; startTop = el.scrollTop;
        });

        listen(document, 'mousemove', function (e) {
            if (!pressed) { return; }
            var dx = e.pageX - startX, dy = e.pageY - startY;
            if (!dragged && Math.abs(dx) < DS_THRESHOLD_PX && Math.abs(dy) < DS_THRESHOLD_PX) { return; }
            if (!dragged) { dragged = true; el.classList.add('ds-grabbing'); }
            e.preventDefault();
            el.scrollLeft = startLeft - dx;
            el.scrollTop = startTop - dy;
        });

        listen(document, 'mouseup', function (e) {
            if (!pressed) { return; }
            pressed = false;
            el.classList.remove('ds-grabbing');
            /* ปล่อยเมาส์นอกพื้นที่ → ไม่มี click วิ่งผ่าน el ให้เคลียร์ธงเอง กันกลืน click ครั้งถัดไป */
            if (dragged && !el.contains(e.target)) { dragged = false; }
        });

        /* ลากจบแล้วอย่าให้ click ทะลุไปสั่งงานของแถว/การ์ดที่อยู่ใต้เมาส์ */
        el.addEventListener('click', function (e) {
            if (!dragged) { return; }
            dragged = false;
            e.stopPropagation();
            e.preventDefault();
        }, true);
    }

    /* รับได้ทั้ง selector, element เดี่ยว และ list ของ element */
    function initDragScroll(target) {
        if (!target) { return; }
        if (typeof target === 'string') {
            Array.prototype.forEach.call(document.querySelectorAll(target), bind);
        } else if (target.nodeType === 1) {
            bind(target);
        } else if (typeof target.length === 'number') {
            Array.prototype.forEach.call(target, bind);
        }
    }

    initDragScroll(targets);
    return function destroy() {
        disposers.splice(0).forEach(function (d) { d(); });
        observers.splice(0).forEach(function (o) { o.disconnect(); });
        bound.splice(0).forEach(function (el) {
            el.removeAttribute('data-ds-bound');
            el.classList.remove('ds-scroll', 'ds-grab', 'ds-grabbing');
        });
    };
}
